    public static JSONObject ensure(JSONObject input,int level){JSONObject s=copy(input);try{int lvl=Math.max(1,Math.min(20,level));if(!supports(s.optString("class_name","")))s.put("class_name",GUNSLINGER);s.put("level",lvl).put("runeterra_gunslinger_runtime",true).put("class_action_auto_rolls",false).put("source_hit_die","1d8").put("firearm_attack_damage_bonus",1).put("firearm_attack_roll_bonus",1).put("saving_throw_proficiencies",new JSONArray().put("Destreza").put("Inteligência"));JSONObject r=s.optJSONObject("class_resources");if(r==null)r=new JSONObject();if(lvl>=2)res(r,"bravura",new DndRulesEngine().proficiencyBonus(lvl),"short_or_long_rest");if(lvl>=18)res(r,"costas_quentes",1,"long_rest");s.put("class_resources",r);JSONArray p=s.optJSONArray("class_choices_pending");if(p==null)p=new JSONArray();if(!s.has("gunslinger_natural_talent_skill"))add(p,"atirador_choose_natural_talent_skill_expertise");if(lvl>=3&&!s.has("subclass_name"))add(p,"atirador_choose_path_pistoleiro_or_armeiro");if(lvl>=13&&!s.has("gunslinger_personal_talisman"))add(p,"atirador_choose_personal_talisman");s.put("class_choices_pending",p);return s;}catch(Exception e){return s;}}
