        if(a.equals("truque de tiro")){if(lvl<7)return blocked(s,"requires_level_7");String zone=n(payload.optString("zone",""));if(!(zone.equals("braco")||zone.equals("cabeca")||zone.equals("perna")||zone.equals("torso")||zone.equals("asa")))return pending(s,"zone(braço|cabeça|perna|torso|asa) + hit_confirmed=true");if(!payload.optBoolean("hit_confirmed",false))return pending(s,"hit_confirmed=true");if(!spend(r,"bravura",1))return blocked(s,"insufficient_bravura");int dc=8+new DndRulesEngine().proficiencyBonus(lvl)+new DndRulesEngine().modifier(s.optInt("dex",10));JSONObject e=new JSONObject().put("zone",payload.optString("zone")).put("save","Constituição").put("save_dc",dc).put("target_save_pending",true);if(zone.equals("braco"))e.put("fail","solta item segurado");else if(zone.equals("cabeca"))e.put("fail","desvantagem em ataques até início do próximo turno");else if(zone.equals("perna"))e.put("fail","caído");else if(zone.equals("torso"))e.put("fail","desvantagem em testes de Força e Destreza até início do próximo turno");else e.put("fail","cai até 60 pés; Enorme+ sucesso automático");return mark(s,"runeterra_shot_trick",e);}
