    private static JSONObject res(JSONObject all,String k,int max,String recharge)throws Exception{JSONObject r=all.optJSONObject(k);if(r==null)r=new JSONObject().put("current",max);r.put("max",max).put("current",Math.min(max,Math.max(0,r.optInt("current",max)))).put("recharge",recharge);all.put(k,r);return r;}private static boolean spend(JSONObject all,String k,int n)throws Exception{JSONObject r=all==null?null:all.optJSONObject(k);if(r==null||r.optInt("current",0)<n)return false;r.put("current",r.optInt("current",0)-n);return true;}private static void restore(JSONObject all,String k)throws Exception{JSONObject r=all==null?null:all.optJSONObject(k);if(r!=null)r.put("current",r.optInt("max",0));}
